mapper.select:
SELECT id, contributor_id, title, description, category_id, place, preview_image, media_url, status, reviewed_at, created_at, updated_at, archived_at, resource_type FROM resource WHERE contributor_id = #{contributorId}
AND title LIKE CONCAT('%', #{keyword}, '%')
AND status = #{status}
AND category_id = #{categoryId}
ORDER BY updated_at DESC, created_at DESC
